method intersection(interval1: (int, int), interval2: (int, int)) returns (result: string)
    requires interval1.0 <= interval1.1 // The start of interval1 should be less than or equal to the end
    requires interval2.0 <= interval2.1 // The start of interval2 should be less than or equal to the end
    ensures result == "YES" || result == "NO" // The result must be either "YES" or "NO"
{
    var start := max(interval1.0, interval2.0);
    var end := min(interval1.1, interval2.1);
    var length := end - start;

    if length < 0 {
        return "NO"; // No intersection
    }

    // Check if length is prime
    if isPrime(length) {
        return "YES";
    } else {
        return "NO";
    }
}

// Helper function to determine if a number is prime
function isPrime(n: int): bool
    requires n >= 0
    ensures result == (n > 1 && forall i: int :: 2 <= i && i * i <= n ==> n % i != 0)
{
    if n <= 1 {
        return false;
    }
    var i := 2;
    while i * i <= n
        invariant 2 <= i <= n
        invariant forall j: int :: 2 <= j && j < i ==> n % j != 0
    {
        if n % i == 0 {
            return false;
        }
        i := i + 1;
    }
    return true;
}
